R = 'RELEASE_METHOD'
RG = ['TRANSFORMATION_LIBRARY.contract-application', 'FOUNDATIONS.result-algebra', 'FOUNDATIONS.result-conjunction']
gate_map = ('For the stated gate, observed incorrect/missing refs, nonmonotonic target, stale accepted plan, defeated lease or unsupported mandatory atomic transport are falsification; unavailable deciding/remote evidence is indeterminate. Established uninterpretable governing basis is invalid_basis and scope/capability exclusion is out_of_frame. Complete support satisfies only that gate. Retain actual evaluation performance and missing slots. Remote effect is separately observed; dispatch or command status does not establish completed or not_started publication/adoption.')
add(R,'release-method','consumer_binding','Release identity, qualification, publication or selection under the selected release contract.',
    'An acceptance claim needs a reacquirable exact release subject and evidence for its predicates; candidate preservation, qualification, acceptance, publication and adoption remain distinct.',
    ['Use core result/conjunction with legal performance pairs, diagnostics, absent coverage and actual effects.', 'Examples require their own actual authorized release binding.'],
    ['No extra evaluation stage or evidence carrier is implied.'], ['Declared release subject, checks, grants, evidence and actual effects.'], RG,
    policy=['Immutable cuts, Git ref profile and monotonic selectors are additional release policy.'])
add(R,'release-publication-context','definition_data','Resolving ownership of release-publication terms.',
    'urn:stdo:bounded-context:release-publication owns identities/transitions for qualifying, publishing and selecting cuts under the complete STDO basis. Product meaning and consumer adoption remain separately owned.',
    ['Do not assign Product meaning or consumer adoption to this context.'], [], ['Selected complete STDO basis and owning Product.'])
add(R,'position','constraint','Handling a release candidate, immutable cut or version-line selector.',
    'Release process evaluates/names/publishes a point-in-time cut downstream of triage; live specification states current law. The local cut is v<version>-rc.<n>, while v<version> discovers the greatest positive published RC ordinal for its project/line.',
    ['Do not use a mutable selector as exact constitutional/dependency/evidence/replay basis.', 'Triage change class, lawful re-entry, affected scope, downstream proof and version disposition before fixes, including RC-window blockers.'],
    ['A local cut name may be the tag in a single-project source; in shared sources it is the qualified ref suffix.'], ['Project namespace, published ordinals, triage and selected exact basis.'], ['SPEC_METHOD.universal-intake-triage'])
add(R,'release-identities','definition_data','Release identity in separately governed Products and observable carriers.',
    {'Project Release Namespace':'stable authority-assigned repository-local key','Project Subtree':'exact repository-relative root and tree at the cut','Candidate Source':'mutable possible successor','RC Branch':'mutable qualified candidate-window carrier','Immutable RC Cut':'annotated qualified tag plus exact Product subject; released Product once accepted','Version-Line Selector':'mutable qualified alias for greatest published RC ordinal','Release Branch':'optional mutable carrier at the selector\'s latest published commit'},
    ['An immutable RC tag never moves.', 'Equal version text and co-location do not merge identities or appoint authority.'],
    ['Branches and version-line selectors may move under their policies.'], ['Assigned namespace, Product subject and release-carrier observations.'], ['TRANSFORMATION_LIBRARY.contract-application'])
add(R,'project-qualified-git-refs','constraint','Future publication in shared release sources, or a declared single-project ref profile.',
    'The authority-assigned namespace matches [a-z0-9]+(?:[-_][a-z0-9]+)*, is slash-free, unique and stable. Shared sources publish refs/heads/rc/<project>/<version>, refs/tags/<project>/v<version>-rc.<n>, refs/tags/<project>/v<version>, and optional refs/heads/release/<project>/<version>.',
    ['Do not infer or reassign namespace from paths, labels, package names or versions.', 'No future unqualified cut/selector in shared sources.', 'Qualify both projects before either next cut when adding a second independently released project.', 'Specification Stack allocations are specification_methodology, axiom_indexer and stdo_representation; these do not imply composition.'],
    ['Unqualified refs remain lawful for exactly one independently released project with a declared profile.'], ['Product authority namespace allocation, project count, declared ref policy and proposed refs.'])
add(R,'project-subtree-release-identity','constraint','Identifying an immutable release in a shared source.',
    'Release identity binds namespace/owner, qualified ref/annotated tag, peeled commit/repository tree, canonical project subtree root/tree, Product member inventory/release-claim bytes and required predecessor/successor dispositions.',
    ['Root locator is . alone or exact slash-separated Git entry bytes with no leading/trailing slash, empty, dot or dot-dot components.', 'Subtree move changes cut locator/identity but not namespace.', 'Root-subtree tree equals repository tree when root is .', 'Exclude unrelated siblings from Product membership; payload digest/inventory alone is insufficient release identity.'],
    [], ['Exact Git objects, namespace authority, inventory, claims and disposition relation.'])
add(R,'historical-ref-and-public-uri-conservation','constraint','Changing from historical unqualified refs to project qualification.',
    'Preserve historical names, tag objects, peels and public links; logical stdo://releases/v<version>-rc.<n>/ remains unchanged. Latest spans preserved historical and future qualified cuts by greatest positive ordinal.',
    ['Do not recreate, reannotate, move or replace historical tag objects.', 'Fail closed if one project-local coordinate names different tag objects.', 'First qualified publication creates the qualified selector; freeze the prior unqualified selector at its existing object.'],
    ['Additional archival refs may preserve reachability of the same historical object.'], ['Historical refs/object identities, URI resolution and project ordinal inventory.'])
add(R,'phases','definition_data','Interpreting the release lifecycle.',
    'Mutable construction precedes immutable RC publication with monotonic discovery, then exact-cut qualification/acceptance/explicit adoption. There is no additional final cut after acceptance.',
    ['Any Product-affecting or release-claim-affecting byte change requires a higher immutable RC for publication and review.', 'Selector discovery advances at publication, not acceptance.'], [], ['Candidate changes and their Product/release-claim scope.'])
add(R,'mutable-candidate-construction','constraint','Before publishing the immutable RC.',
    'Candidate work is triaged and explicitly non-operative for released consumers; Product boundary, release claims, excluded mutable state and qualification basis are explicit before publication.',
    ['Reprice material scope changes rather than absorb them silently.'],
    ['Bounded triaged fixes, continuing qualification/operator review, draft notes and a moving RC branch are allowed.'], ['Triaged scope, selected release boundary and proposed changes.'])
add(R,'immutable-rc-publication','constraint','Publishing one exact immutable RC.',
    'Publication establishes the declared cut and required public-ref relation at the selected remote after triage, subject/claim declaration, asset reconciliation, proportionate prechecks, commit, subtree resolution and annotated cut/selector creation.',
    ['Record namespace, subtree root/tree and reacquirable ref/identity/inventory evidence.', 'Shared source cut and selector tags target the same commit; push carrier, RC branch, cut, selector and optional release branch atomically where supported.', 'Verify remotely the highest RC relationship.', 'Never move published immutable cuts; higher same-line RCs handle bounded repairs while the line remains applicable.', 'Published higher RC without matching selector advancement is an invalid fail-closed state, not permission to resolve an old latest.', 'After uncertain dispatch, observe remote state and complete/repair only still-authorized missing relations.'],
    ['A bounded review repair alone does not require a minor-version increase.'], ['Triaged scope, exact objects/inventory, prechecks, operation grant, remote capabilities and remote ref observations.'], RG, gate_map)
add(R,'exact-cut-qualification','constraint','Qualifying or accepting the exact immutable RC and its declared claim set.',
    'Each qualification claim binds namespace/ref/tag/commit/repository-tree/subtree/member set, release-claim bytes, Product/release basis, property/observation boundary, evidence/verdict/gaps and complete predecessor relation. Required claims conjoin without enlarging witness scope.',
    ['Source proof does not prove installed/package behavior; packaging equivalence does not prove semantics; presence proves usability only if presence is the actual claim.', 'Acceptance requires completed exact-cut/operator checks and human acceptance of that exact subject.', 'Qualifying-byte changes keep old verdicts attached to the old RC and require a higher RC; acceptance does not move selector or create final carrier.'],
    ['Supported alternative realizations use the same claim conditions; Product owns lawful scope narrowing.'], ['Exact RC identity, declared claims, actual witnesses/performance/effects, independent review where required, operator checks and human acceptance.'], RG,
    'passed satisfies only with performed evaluation and complete exact-cut evidence/coverage; admissible failed counterevidence falsifies; skipped/cached-green/raw labels lacking deciding support are indeterminate. Preserve established scope/basis diagnoses, independent counterevidence, actual performance and effects. Missing judgment stays an absent slot; conjunction keeps a known failure beside it. Qualification, owner acceptance and consumer adoption remain separate predicates.')
add(R,'monotonic-version-line-advancement','constraint','Publishing the next highest immutable RC on one project/version line.',
    'Advance an absent or lower-ordinal selector to a matching annotated immutable RC only when no higher ordinal exists; align optional release branch and verify remote selector/cut at the highest commit.',
    ['Prepare annotated selector and optional release branch, push the complete carrier/ref relation atomically where supported, and verify remotely.', 'Refuse missing annotated cut, existing higher ordinal, downgrade or misaligned selector/release branch.', 'Repair later defects by higher RC, never moved old RC or selector rollback.'], [], ['Complete published ordinal set, old selector/release branch, target annotated cut and remote effect evidence.'], RG, gate_map)
add(R,'selector-and-consumer-adoption','constraint','Resolving a channel or mutating consumer Product Definitions to adopt a release.',
    'Channel discovery selects the greatest positive published project RC ordinal and requires annotated cut/selector peels at the same commit. Consumer authority is the pinned immutable URI plus manifest digest; adoption occurs only after a separately presented digest-bound plan is accepted and rederived unchanged.',
    ['Enumerate preserved historical cuts during namespace transitions; fail closed on selector lag, other target or missing annotated selector peel.', 'Refuse channel adoption below the consumer\'s current same-line exact ordinal.', 'Plan binds current definition bytes/basis, target immutable cut/tag/commit/tree/manifest; selector/target/manifest/definition drift invalidates acceptance.', 'Fleet mutation requires the aggregate exact per-definition-plan digest; a mutating invocation cannot present/authorize its own plan.'],
    ['A channel may remain as discovery selector.', 'Explicit immutable-URI/digest exact-basis operations such as sync may intentionally retain an older cut.'], ['Published tags/peels, current Product Definition bytes/basis, target manifest, externally accepted plan digest and fresh rederivation.'], RG, gate_map)
add(R,'naming','definition_data','Selecting release-source ref spelling.',
    'Default shared names are rc/<project>/<version>, <project>/v<version>-rc.<n>, optional release/<project>/<version> and <project>/v<version>.',
    ['Retain namespace, mutable carrier, immutable cut and mutable selector distinctions.'],
    ['Unqualified names obey single-project/historical rules.', 'Another spelling is allowed only where ref policy proves collision freedom and preserves those distinctions.'], ['Release-source ref policy and namespace assignments.'], ['RELEASE_METHOD.project-qualified-git-refs','RELEASE_METHOD.historical-ref-and-public-uri-conservation'])
add(R,'release-scoped-assets','constraint','Using release notes, manifests, dependencies, package metadata, receipts or ref-identity declarations.',
    'Reconcile each used release-scoped surface to the exact RC before publication; any later changed asset byte is a new candidate requiring a higher RC.',
    ['Keep version branding out of live Product/requirements merely to signal recency; exact versions belong in release carriers and consumer basis.'],
    ['Selector has no content-reconciliation phase because it adds no Product bytes.'], ['Used release surfaces, frozen bytes and proposed deltas.'])
add(R,'coordinated-release-matched-asset-cohorts','constraint','An explicit authority-declared cross-Product release-matched cohort.',
    'Every required Product/asset has the same exact <version>-rc.<n> suffix and exact declared source dependency, owners, qualification/publication boundary and reproducible source-member/digest closure.',
    ['Normalize only the leading v in cut names; version equality does not merge Products, inventories, tags, acceptance or authorities.', 'STDO stack includes corpus, distributed spec plugin/host assets, validating Axiom Indexer, STDO Representation, and released a_c.STDO program/index with complete source inventory/digests/cut.', 'Missing, stale, mismatched-version/source or unreproducible members defeat completeness.', 'Source-member change invalidates derived successor index: regenerate, validate, independently qualify where required and release under same new cut; old index remains historical only.'],
    ['Cohort declaration is optional and explicit; no relation follows from co-location, equal version or shared actor.'], ['Authority declaration, complete required set, source digest closure and actual member identities/qualification.'], RG,
    'The cohort-relation predicate satisfies only with established complete coverage; observed missing/incongruent member falsifies; unavailable/unobserved closure evidence is indeterminate, preserving scope/basis diagnoses. Unknown set is not empty. Publication effect is separately observed.')
add(R,'two-commit-construction-and-one-publication-transaction','constraint','Normal publication of a coordinated STDO cohort.',
    'Commit A freezes corpus/plugin/release/qualification and local annotated STDO tag; its installed verified manifest feeds child/index/cohort bytes frozen at B. Qualify B before child tags, then qualify the full annotated local ref graph and fetched remote expectations before one atomic publication.',
    ['Prepare every child cut, RC branch, selector and optional release branch; post-tag gate binds objects/peels/versions/targets/exact push set and expected remote OID or absence for every destination.', 'Atomic transport is mandatory: no sequential fallback.', 'Immutable tags are create-only with bound remote absence; every mutable destination uses an explicit per-ref compare-and-swap lease in the same transaction.', 'Missing expectation, unexpected tag or changed OID stops publication; refetch and repeat complete content/local-ref qualification before another push.', 'No unguarded force, partial push or in-place expectation update after lease mismatch.', 'Remote verification rejects absent/lightweight/mismatched/wrong-target refs; later bookkeeping cannot move immutable tags.'],
    ['Later bookkeeping commit is allowed without altering immutable cohort tags.'], ['A/B bytes, local verified manifest, full local graph, remote expectations, transport capability, actual leases and remote observations.'], RG, gate_map)
add(R,'qualification-and-recovery','constraint','Qualifying, resuming or recovering cohort publication.',
    'Content qualification binds A tag/manifest, B tree, target refs/versions/inventories/index/digest closure; post-tag local qualification binds annotated objects/peels/commits/push set/remote expectations to unchanged content; remote qualification verifies the same complete relation.',
    ['Resumption observes actual local/remote state; assumed atomicity does not prove completed publication.', 'Recovery effects require an existing authorized recovery relation; context acquisition grants no ref/repository reset.', 'New cohort law changes qualifying bytes and governs a higher RC only.'],
    ['Separately authorized same-version historical backfill may bind exact historical cut/name; it cannot move old tag, add Product bytes, or claim an atomic cohort existed at original publication.'], ['Frozen content/local/remote evidence and explicit recovery exception if selected.'], RG, gate_map)
add(R,'product-subject-and-repository-carrier','definition_data','Declaring the release subject before qualification.',
    'Namespace/subtree, exact Product members/artifact and release-claim surfaces are declared separately from excluded co-located mutable source state; repository commit is their wider carrier.',
    ['Do not infer sibling or co-located membership from the commit.', 'No later carrier delta enters an immutable RC; publication-caused ticket/source bookkeeping stays on continuing source and cannot move its tag.'], [], ['Declared member/claim/exclusion sets and exact subtree tree.'])
add(R,'acceptance-criteria','constraint','Accepting an immutable RC.',
    'Acceptance needs passed pre-RC qualification, required independent exact-cut review, completed operator review, stable intended scope/successor relation, accurate release assets, closed release blockers or explicit scope narrowing, and human Product acceptance of exact RC identity.',
    ['Keep qualification, authorized owner acceptance and consumer adoption distinct.', 'Acceptance neither advances nor rolls back selector; adoption separately uses accepted digest-bound plan.'],
    ['Release blockers may be resolved by explicit lawful scope narrowing.'], ['Required reviews/checks, scope, assets, gaps, narrowing authority and human decision bound to exact identity.'], RG)
add(R,'external-qualification-dependencies','constraint','A release claim depends on an external backend, transport or operator service.',
    'The claim is qualified with a healthy required dependency or explicitly narrowed before acceptance; skipping due to unhealthy dependency does not prove the dependent capability.',
    ['Keep release-claim dependency separate from Product carrier/migration classification.'],
    ['An external dependency may remain out of Product while blocking the claim.'], ['External dependency condition, affected claim, qualification evidence and authorized narrowing.'], RG)
add(R,'successor-baseline-conservation-stdo-up-015','constraint','A successor evolves semantic claims from an identified exact immutable predecessor; maintenance/support changes can affect retained claims.',
    'Fix the predecessor origin for the candidate and disposition every claim capable of successor effect as conserved, accepted supersession, current-authority intentional removal or supported non-applicability, with its own semantic and decision predicates.',
    ['Conserved means retained meaning; superseded needs actual accepted replacement; intentionally removed needs actual current Product removal; not-applicable needs bounded no-effect evidence and no silent narrowing.', 'Unresolved disposition blocks the affected claim\'s qualification; recording does not supply the needed acceptance/removal authority.', 'Semantic evidence, not patch absence/naming/code similarity, establishes conservation.', 'For relevant support lines bind watched source, observation boundary, inclusion policy and candidate; disposition relevant changes at material integration and exact-cut qualification.'],
    ['Any supported realization can show retention/replacement; consumer chooses record, comparison, branch strategy and proof.'], ['Exact predecessor/successor claim relation, semantic witnesses, actual authority decisions and watched-line observations.'], RG,
    'Assess retained-meaning, replacement, exclusion or no-effect on each exact row: support satisfies, counterexample falsifies, missing evidence/reason is indeterminate, retaining scope/basis diagnoses/performance/coverage. Separately assess that disposition D was made under mandate: actual authorized decision satisfies; demonstrated absent/unauthorized decision falsifies; unconfirmed authority/decision/reason is indeterminate. Removal/non-applicability satisfaction is not retention. Neither result erases the other or effects.')
